use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { let lmdfb_data = fs :: read_to_string ("lmdfb_lattice_mapping.json") ? ; let lmdfb : serde_json :: Value = serde_json :: from_str (& lmdfb_data) ? ; let mut usage_analysis : HashMap < i32 , ConstantUsage > = HashMap :: new () ; if let Some (nodes) = lmdfb ["nodes"] . as_object () { for (symbol , _node) in nodes { analyze_symbol_usage (symbol , & mut usage_analysis) ; } } let mut sorted_usage : Vec < _ > = usage_analysis . into_values () . collect () ; sorted_usage . sort_by (| a , b | b . count . cmp (& a . count)) ; println ! ("🔍 Constant Usage Type Analysis:") ; println ! ("Value | Count | Primary Usage Types") ; println ! ("------|-------|-------------------") ; for usage in sorted_usage . iter () . take (15) { let primary_types = usage . usage_types . iter () . take (3) . cloned () . collect :: < Vec < _ > > () . join (", ") ; println ! ("{:5} | {:5} | {}" , usage . value , usage . count , primary_types) ; } let mut categories = HashMap :: new () ; for usage in & sorted_usage { let category = categorize_usage (usage . value , & usage . contexts) ; categories . entry (category) . or_insert_with (Vec :: new) . push (usage . value) ; } println ! ("\n📊 Usage Categories:") ; for (category , values) in categories { println ! ("🎯 {}: {:?}" , category , values . iter () . take (10) . collect ::< Vec < _ >> ()) ; } Ok (()) }